from copy import deepcopy


def part(heading, text, formula=None, blocks=None):
    result=dict(lead=heading, text=text)
    if formula:result['formula']=formula
    if blocks:result['blocks']=blocks
    return result


def answer(title, chapter, keywords, *sections):
    return dict(title=title,chapter=chapter,keywords=keywords.split('|'),steps=list(sections))


