# Complete responses to the additional clauses of individual source questions.
POINT_TRANSFORMS=part('Ba biến đổi mức xám cơ bản',
    'Âm bản s=L−1−r đảo sáng thành tối và ngược lại. Biến đổi log mở rộng các mức tối và nén các mức cao. Biến đổi lũy thừa dùng để hiệu chỉnh gamma; với đầu vào chuẩn hóa trong [0,1], γ<1 làm sáng và γ>1 làm tối. Trong hàm log và lũy thừa, c là hệ số tỷ lệ.',
    r's=L-1-r,\quad s=c\ln(1+r),\quad s=c r^\gamma')

def resolve_answer(ident,concept):
    if ident in ['bank-2-3','uyen-lt-2-3']:
        return deepcopy(THEORY['vector'])
    result=deepcopy(THEORY[concept])
    if ident=='bank-1-11':
        result['steps']=[deepcopy(THEORY['noise']['steps'][0]),deepcopy(THEORY['noise']['steps'][2])]+deepcopy(THEORY['edge']['steps'])
    elif ident=='uyen-lt-1-11':
        result['steps']=[result['steps'][0],result['steps'][2]]
    elif ident=='uyen-3-L1':result['steps'].append(deepcopy(POINT_TRANSFORMS))
    elif ident=='uyen-5-L1':
        result['steps']+=deepcopy([THEORY['kernels']['steps'][1],THEORY['kernels']['steps'][2],THEORY['kernels']['steps'][-1]])
    elif ident=='uyen-5-L8':result['steps']+=deepcopy(THEORY['triangle']['steps'])
    # No formula or reasoning is dropped when a source asks more than one topic.
    return result


